1	package main
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// These tests cover the CLI contract for a damaged committed definition:
12	// every data command fails at open with exit code 3 (the existing read-
13	// failure code), prints no success record / artifact / input-check verdict,
14	// and leaves data.json byte-for-byte in place.
15	const cliCorruptDef = `{"modulus":"7","constraints":[
16		{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`
17	
18	type cliResult struct {
19		code int
20		out  string
21		err  string
22	}
23	
24	func callCLI(t *testing.T, args ...string) cliResult {
25		t.Helper()
26		code, out, errOut := runCapture(t, args...)
27		return cliResult{code, out, errOut}
28	}
29	
30	// seedCorruptibleStore drives the CLI through a legal create + import
31	// (optionally freeze + compile), applies mutate to the parsed data.json and
32	// returns the damaged bytes now on disk.
33	func seedCorruptibleStore(t *testing.T, dir string, freezeAndCompile bool, mutate func(map[string]any)) []byte {
34		t.Helper()
35		work := filepath.Dir(dir)
36		defPath := writeFile(t, work, "def.json", cliCorruptDef)
37		must := func(what string, r cliResult) {
38			t.Helper()
39			if r.code != 0 {
40				t.Fatalf("%s: code=%d err=%s", what, r.code, r.err)
41			}
42		}
43		must("create", callCLI(t, "circuit-create", "--dir", dir, "--name", "mul", "--version", "1",
44			"--constraints", "1", "--public-inputs", "1", "--private-inputs", "1"))
45		must("import", callCLI(t, "constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
46			"--file", defPath))
47		if freezeAndCompile {
48			must("freeze", callCLI(t, "circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"))
49			must("compile", callCLI(t, "circuit-compile", "--dir", dir, "--name", "mul", "--version", "1"))
50		}
51	
52		path := filepath.Join(dir, "data.json")
53		raw, err := os.ReadFile(path)
54		if err != nil {
55			t.Fatal(err)
56		}
57		var env map[string]any
58		if err := json.Unmarshal(raw, &env); err != nil {
59			t.Fatal(err)
60		}
61		mutate(env)
62		bad, err := json.MarshalIndent(env, "", "  ")
63		if err != nil {
64			t.Fatal(err)
65		}
66		bad = append(bad, '\n')
67		if err := os.WriteFile(path, bad, 0o644); err != nil {
68			t.Fatal(err)
69		}
70		return bad
71	}
72	
73	// TestCLICorruptDefinitionExitCode drives each shape of damage through the
74	// CLI: regardless of draft or frozen/compiled state, reads, compilation and
75	// input checks must exit 3 without touching the file.
