635	// ---- strict decoding of persisted definitions -----------------------------
636	//
637	// The persist shapes below are part of the committed data file rather than an
638	// import request, so their UnmarshalJSON methods demand the exact shape the
639	// importer writes and tag every shape failure as data corruption. This runs
640	// while the envelope is being read, before validateEnvelope: a definition that
641	// omits a side array or a term's wire/coeff — which a plain struct decode
642	// would silently turn into a nil slice or a zero int/string — is refused at
643	// read time instead of being mistaken for an empty array, wire 0 or an empty
644	// coefficient. Null in place of one of these fields, a null element inside an
645	// array, a non-object term and an unknown/duplicate member are refused the
646	// same way.
647	//
648	// An explicitly empty side array still decodes to the zero linear combination
649	// and an explicit wire:0 still names the constant wire; both are ordinary
650	// values and stay legal. The circuit record's definition pointer itself may
651	// be absent or null: encoding/json leaves the pointer nil without invoking
652	// these methods, which is exactly the legacy counts-only state.
653	//
654	// These decoders enforce shape only. The semantic rules (prime modulus,
655	// wire range, constraint count) are re-checked by validateEnvelope through
656	// the same definitionFromPersist pipeline used after a clean import.
657	
658	// asCorrupt retags a structural decode failure as data corruption. The
659	// strict-JSON helpers describe shape problems with ErrInvalidArgument, the
660	// right kind for a rejected import request but not for damage discovered in
661	// already-committed data.
662	func asCorrupt(err error) error {
663		if err == nil {
664			return nil
665		}
666		var se StoreError
667		if errors.As(err, &se) {
668			return StoreError{Kind: ErrDataCorrupt.Kind, Detail: se.Detail}
669		}
670		return corruptf("%v", err)
671	}
672	
673	func (p *persistDefinition) UnmarshalJSON(raw []byte) error {
674		members, err := strictObject(raw, []string{"modulus", "constraints"}, "stored constraint definition")
675		if err != nil {
676			return asCorrupt(err)
677		}
678		modulusRaw, err := requireMember(members, "modulus", "stored constraint definition")
679		if err != nil {
680			return asCorrupt(err)
681		}
682		constraintsRaw, err := requireMember(members, "constraints", "stored constraint definition")
683		if err != nil {
684			return asCorrupt(err)
685		}
686		modulusText, err := decodeJSONString(modulusRaw, "stored modulus")
687		if err != nil {
688			return asCorrupt(err)
689		}
690		if string(bytes.TrimSpace(constraintsRaw)) == "null" {
691			return corruptf("stored constraint definition field \"constraints\" must be an array, not null")
692		}
693		var constraints []persistConstraint
694		if err := json.Unmarshal(constraintsRaw, &constraints); err != nil {
695			var se StoreError
696			if errors.As(err, &se) {
697				return err // already reported as data corruption by an inner decoder
698			}
699			return corruptf("stored constraint definition field \"constraints\" must be an array: %v", err)
700		}
701		*p = persistDefinition{Modulus: modulusText, Constraints: constraints}
702		return nil
703	}
704	
705	func (c *persistConstraint) UnmarshalJSON(raw []byte) error {
706		if string(bytes.TrimSpace(raw)) == "null" {
707			return corruptf("stored constraint must be a JSON object, not null")
708		}
709		members, err := strictObject(raw, []string{"a", "b", "c"}, "stored constraint")
710		if err != nil {
711			return asCorrupt(err)
712		}
713		var out persistConstraint
714		for _, side := range []struct {
715			key string
716			dst *[]persistTerm
717		}{
718			{"a", &out.A}, {"b", &out.B}, {"c", &out.C},
719		} {
720			sideRaw, err := requireMember(members, side.key, "stored constraint")
721			if err != nil {
722				return asCorrupt(err)
723			}
724			terms, err := decodePersistTerms(sideRaw, side.key)
725			if err != nil {
726				return err
727			}
728			*side.dst = terms
729		}
730		*c = out
731		return nil
732	}
