734	// decodePersistTerms decodes one a/b/c array, rejecting null and any element
735	// that is not a well-formed term object.
736	func decodePersistTerms(raw json.RawMessage, side string) ([]persistTerm, error) {
737		if string(bytes.TrimSpace(raw)) == "null" {
738			return nil, corruptf("stored constraint side %q must be an array, not null", side)
739		}
740		var terms []persistTerm
741		if err := json.Unmarshal(raw, &terms); err != nil {
742			var se StoreError
743			if errors.As(err, &se) {
744				return nil, err // a null/malformed element already reported corruption
745			}
746			return nil, corruptf("stored constraint side %q must be an array: %v", side, err)
747		}
748		return terms, nil
749	}
