751	func (t *persistTerm) UnmarshalJSON(raw []byte) error {
752		if string(bytes.TrimSpace(raw)) == "null" {
753			return corruptf("stored term must be a JSON object, not null")
754		}
755		members, err := strictObject(raw, []string{"wire", "coeff"}, "stored term")
756		if err != nil {
757			return asCorrupt(err)
758		}
759		wireRaw, err := requireMember(members, "wire", "stored term")
760		if err != nil {
761			return asCorrupt(err)
762		}
763		coeffRaw, err := requireMember(members, "coeff", "stored term")
764		if err != nil {
765			return asCorrupt(err)
766		}
767		wire, err := decodeJSONInt(wireRaw, "stored term wire")
768		if err != nil {
769			return asCorrupt(err)
770		}
771		coeff, err := decodeJSONString(coeffRaw, "stored term coefficient")
772		if err != nil {
773			return asCorrupt(err)
774		}
775		t.Wire = wire
776		t.Coeff = coeff
777		return nil
778	}
