780	// ---- input checking -------------------------------------------------------
781	
782	// parseWitness validates the check input JSON and tags every rejection as an
783	// input format error (ErrInvalidInput), distinct from domain rule failures.
784	func parseWitness(raw []byte, public, private int) (Witness, error) {
785		w, err := parseWitnessDocument(raw, public, private)
786		if err != nil {
787			var se StoreError
788			if errors.As(err, &se) {
789				return Witness{}, StoreError{Kind: ErrInvalidInput.Kind, Detail: se.Detail}
790			}
791			return Witness{}, inputFormatf("%v", err)
792		}
793		return w, nil
794	}
795	
796	// parseWitnessDocument parses and validates a check input document: both
797	// groups must be present as arrays, their lengths must match the
798	// declaration, and every value must be an arbitrarily long signed decimal
799	// string.
800	//
801	// Privacy rule. Diagnostics for the private group never quote a private
802	// value, a character or fragment taken from one, an object key found inside
803	// the private array, or the raw bytes the parser ran into. Private problems
804	// are identified structurally instead — the 1-based private input index, the
805	// group name and the required shape — so a caller can repair the document
806	// without learning its private contents. Public diagnostics keep their full
807	// detail. When a document is too damaged to tell which group a token belongs
808	// to, it is rejected generically as malformed JSON with no source quoted.
809	func parseWitnessDocument(raw []byte, public, private int) (Witness, error) {
810		members, err := splitWitnessObject(raw)
811		if err != nil {
812			return Witness{}, err
813		}
814		publicRaw, havePublic := members["public"]
815		privateRaw, havePrivate := members["private"]
816		if !havePublic {
817			return Witness{}, invalidf("input is missing required field %q: the public group must be an array of decimal strings", "public")
818		}
819		if !havePrivate {
820			return Witness{}, invalidf("input is missing required field %q: the private group must be an array of decimal strings", "private")
821		}
822		pubValues, err := parsePublicArray(publicRaw)
823		if err != nil {
824			return Witness{}, err
825		}
826		privValues, err := parsePrivateArray(privateRaw)
827		if err != nil {
828			return Witness{}, err
829		}
830		return witnessFromArrays(pubValues, privValues, public, private)
831	}
832	
833	// splitWitnessObject walks only the top-level {"public":…,"private":…}
834	// envelope and returns each member's raw value. It exists to attribute a
835	// lexical failure to the right group before the value is decoded, so a
836	// syntax error inside the private value can be reported without quoting the
837	// character the decoder met there.
838	//
839	// Top-level key names are fixed schema names ("public"/"private"), so
840	// quoting an unknown or duplicated top-level field cannot disclose a
841	// private value. A failure while reading a key or the opening/closing brace
842	// is unattributable and reported as plain malformed JSON with no source text.
843	func splitWitnessObject(raw []byte) (map[string]json.RawMessage, error) {
844		trimmed := bytes.TrimSpace(raw)
845		if len(trimmed) == 0 || trimmed[0] != '{' {
846			return nil, invalidf("input must be a JSON object with %q and %q arrays", "public", "private")
847		}
848		dec := json.NewDecoder(bytes.NewReader(trimmed))
849		open, err := dec.Token()
850		if err != nil || open != json.Delim('{') {
851			return nil, invalidf("input is not valid JSON")
852		}
853		members := make(map[string]json.RawMessage)
854		for dec.More() {
855			keyTok, err := dec.Token()
856			if err != nil {
857				return nil, invalidf("input is not valid JSON")
858			}
859			key, ok := keyTok.(string)
860			if !ok {
861				return nil, invalidf("input is not valid JSON")
862			}
863			if key != "public" && key != "private" {
864				return nil, invalidf("input has unknown field %q: only %q and %q are allowed", key, "public", "private")
865			}
866			if _, duplicated := members[key]; duplicated {
867				return nil, invalidf("input contains duplicate field %q", key)
868			}
869			var value json.RawMessage
870			if err := dec.Decode(&value); err != nil {
871				if key == "private" {
872					// Inside the private section: describe the problem, never the
873					// character, offset or fragment the parser encountered.
874					return nil, invalidf("input field %q is not valid JSON: the private group must be an array of decimal strings", key)
875				}
876				return nil, invalidf("input field %q is not valid JSON: %v", key, err)
877			}
878			members[key] = value
879		}
880		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
881			return nil, invalidf("input is not valid JSON")
882		}
883		// Anything after the top-level object (including more JSON tokens) is
884		// trailing data at an unattributable location; report it generically.
885		if _, err := dec.Token(); err != io.EOF {
886			return nil, invalidf("input is not valid JSON: trailing data after the object")
887		}
888		return members, nil
889	}
890	
891	// parsePublicArray decodes the public group with full diagnostics. Public
892	// input is not confidential, so the underlying parser error — including the
893	// offending value — is retained.
894	func parsePublicArray(raw json.RawMessage) ([]string, error) {
895		const which = "public"
896		if string(bytes.TrimSpace(raw)) == "null" {
897			return nil, invalidf("input field %q must be an array of decimal strings, not null", which)
898		}
899		var values []string
900		if err := json.Unmarshal(raw, &values); err != nil {
901			return nil, invalidf("input field %q must be an array of decimal strings: %v", which, err)
902		}
903		return values, nil
904	}
905	
906	// parsePrivateArray decodes the private group without ever quoting its
907	// contents. Each element must be a JSON string; a number, boolean, null,
908	// object or nested array is rejected by its 1-based position alone. An
909	// object element is rejected at its opening brace and never descended into,
910	// so a duplicate key (or any key) inside it cannot be reported.
911	func parsePrivateArray(raw json.RawMessage) ([]string, error) {
912		const which = "private"
913		trimmed := bytes.TrimSpace(raw)
914		if len(trimmed) == 0 || string(trimmed) == "null" || trimmed[0] != '[' {
915			return nil, invalidf("input field %q must be an array of decimal strings", which)
916		}
917		dec := json.NewDecoder(bytes.NewReader(trimmed))
918		dec.UseNumber()
919		if open, err := dec.Token(); err != nil || open != json.Delim('[') {
920			return nil, invalidf("input field %q is not valid JSON: it must be an array of decimal strings", which)
921		}
922		values := []string{}
923		index := 0
924		for dec.More() {
925			index++
926			tok, err := dec.Token()
927			if err != nil {
928				return nil, invalidf("input field %q is not valid JSON: element #%d must be a decimal string", which, index)
929			}
930			switch t := tok.(type) {
931			case string:
932				values = append(values, t)
933			case json.Delim:
934				kind := "array"
935				if t == '{' {
936					kind = "object"
937				}
938				return nil, invalidf("private input #%d must be a decimal string, not an %s", index, kind)
939			case json.Number, float64:
940				return nil, invalidf("private input #%d must be a decimal string, not a number", index)
941			case bool:
942				return nil, invalidf("private input #%d must be a decimal string, not a boolean", index)
943			case nil:
944				return nil, invalidf("private input #%d must be a decimal string, not null", index)
945			}
946		}
947		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
948			return nil, invalidf("input field %q is not valid JSON: it must be an array of decimal strings", which)
949		}
950		return values, nil
951	}
952	
953	// witnessFromArrays applies the single witness grammar and layout rule
954	// shared by both check entry points: each group must contain exactly the
955	// declared number of decimal strings. A nil slice is accepted wherever an
956	// empty one would be (an in-API witness declaring zero inputs); unlike the
957	// JSON entry point nothing here distinguishes "omitted" from "empty".
958	// Private values are never echoed; private problems are identified by index.
959	func witnessFromArrays(pubValues, privValues []string, public, private int) (Witness, error) {
960		if len(pubValues) != public {
961			return Witness{}, invalidf("public input array has %d values but the version requires %d decimal strings",
962				len(pubValues), public)
963		}
964		if len(privValues) != private {
965			return Witness{}, invalidf("private input array has %d values but the version requires %d decimal strings",
966				len(privValues), private)
967		}
968		if err := validateWitnessValues(pubValues, "public", true); err != nil {
969			return Witness{}, err
970		}
971		if err := validateWitnessValues(privValues, "private", false); err != nil {
972			return Witness{}, err
973		}
974		return Witness{Public: pubValues, Private: privValues}, nil
975	}
976	
977	// validateWitnessValues checks that every entry is an arbitrarily long
978	// signed decimal string. Public values may be echoed with the parser's
979	// detailed reason; private values are never quoted, and their failure is
980	// described structurally (see signedDecimalKind) with a 1-based index.
981	func validateWitnessValues(values []string, which string, echo bool) error {
982		for i, v := range values {
983			if _, err := parseBigSignedDecimal(v); err != nil {
984				if echo {
985					return invalidf("%s input #%d value %q is not a decimal integer: %v", which, i+1, v, err)
986				}
987				return invalidf("%s input #%d is not a decimal integer: %s", which, i+1, signedDecimalKind(v))
988			}
989		}
990		return nil
991	}
992	
993	// evaluate checks every constraint against the witness and returns the
994	// 1-based index of the first failure, or 0 when all hold.
995	func (d *canonicalDefinition) evaluate(w Witness) int {
996		p := d.modulus
997		// Wire layout: 0 = 1, then public inputs, then private inputs.
998		values := make([]int64, 1+d.public+d.private)
999		values[0] = 1
1000		bigP := big.NewInt(p)
1001		for i, s := range w.Public {
1002			n, _ := parseBigSignedDecimal(s)
1003			n.Mod(n, bigP)
1004			values[1+i] = n.Int64()
1005		}
1006		for i, s := range w.Private {
1007			n, _ := parseBigSignedDecimal(s)
1008			n.Mod(n, bigP)
1009			values[1+d.public+i] = n.Int64()
1010		}
1011		combo := func(terms []parsedTerm) int64 {
1012			var sum int64
1013			for _, t := range terms {
1014				// sum < p and the product < (p-1)^2 < 2^62, so this add never
1015				// overflows int64.
1016				sum = modInt64(sum+t.value*values[t.wire], p)
1017			}
1018			return sum
1019		}
1020		for i, con := range d.constraints {
1021			av := combo(con.a)
1022			bv := combo(con.b)
1023			cv := combo(con.c)
1024			if modInt64(av*bv, p) != cv {
1025				return i + 1
1026			}
1027		}
1028		return 0
1029	}
